String formatName = String.format("%s", "png");
net.coobird.thumbnailator.Thumbnails.of(sourceImage)
    .size(10, 10)
    .outputFormat(formatName)
    .toOutputStream(imageBytes);

byte[] outBytes = imageBytes.toByteArray();
assert outBytes.length > 8 : "Output image is too small";
// Verify the PNG magic number to ensure the format was applied correctly
assert outBytes[1] == 'P' && outBytes[2] == 'N' && outBytes[3] == 'G' : "Output is not in PNG format";

System.out.println("__CHECK__ format " + outBytes.length);

