net.coobird.thumbnailator.geometry.Size size = new net.coobird.thumbnailator.geometry.AbsoluteSize(42, 42);
net.coobird.thumbnailator.geometry.Region region = new net.coobird.thumbnailator.geometry.Region(
    net.coobird.thumbnailator.geometry.Positions.BOTTOM_RIGHT,
    size
);

net.coobird.thumbnailator.geometry.Size retrievedSize = region.getSize();
java.awt.Dimension dim = retrievedSize.calculate(100, 100);

assert dim.width == 42 && dim.height == 42 : "Retrieved size should match the initialized AbsoluteSize of 42x42";
System.out.println("__CHECK__ getSize " + dim.width + "x" + dim.height);

